CREATE TABLE knowledge_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE generations (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, registry_hash TEXT NOT NULL, registry_raw TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('building','ready'))) STRICT;
CREATE TABLE documents (generation TEXT NOT NULL REFERENCES generations(id) ON DELETE CASCADE, id TEXT NOT NULL, inn TEXT NOT NULL, label TEXT NOT NULL, file TEXT NOT NULL, sha256 TEXT NOT NULL, content TEXT NOT NULL, raw_json TEXT NOT NULL, PRIMARY KEY(generation,id)) STRICT;
CREATE TABLE sections (generation TEXT NOT NULL, id TEXT NOT NULL, document_id TEXT NOT NULL, parent_id TEXT, level INTEGER NOT NULL, title TEXT NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL CHECK(end_offset>=start_offset), line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, page_start TEXT, page_end TEXT, PRIMARY KEY(generation,id), FOREIGN KEY(generation,document_id) REFERENCES documents(generation,id) ON DELETE CASCADE) STRICT;
CREATE TABLE chunks (generation TEXT NOT NULL, id TEXT NOT NULL, document_id TEXT NOT NULL, section_id TEXT NOT NULL, section_ids TEXT NOT NULL CHECK(json_valid(section_ids)), ordinal INTEGER NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL CHECK(end_offset>start_offset), content TEXT NOT NULL, content_hash TEXT NOT NULL, oversize INTEGER NOT NULL CHECK(oversize IN (0,1)), line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, page_start TEXT, page_end TEXT, PRIMARY KEY(generation,id), UNIQUE(generation,document_id,ordinal), FOREIGN KEY(generation,document_id) REFERENCES documents(generation,id) ON DELETE CASCADE, FOREIGN KEY(generation,section_id) REFERENCES sections(generation,id)) STRICT;
CREATE TABLE effects (generation TEXT NOT NULL REFERENCES generations(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, category TEXT, status TEXT NOT NULL CHECK(status='review-required'), raw_json TEXT NOT NULL, PRIMARY KEY(generation,id)) STRICT;
CREATE TABLE effect_aliases (generation TEXT NOT NULL, effect_id TEXT NOT NULL, alias TEXT NOT NULL, normalized TEXT NOT NULL, PRIMARY KEY(generation,effect_id,alias), FOREIGN KEY(generation,effect_id) REFERENCES effects(generation,id) ON DELETE CASCADE) STRICT;
CREATE INDEX effect_aliases_normalized ON effect_aliases(generation,normalized);
CREATE TABLE blocks (generation TEXT NOT NULL, id TEXT NOT NULL, document_id TEXT NOT NULL, raw_json TEXT NOT NULL, PRIMARY KEY(generation,id), FOREIGN KEY(generation,document_id) REFERENCES documents(generation,id) ON DELETE CASCADE) STRICT;
CREATE TABLE source_mentions (generation TEXT NOT NULL, id TEXT NOT NULL, document_id TEXT NOT NULL, raw_json TEXT NOT NULL, PRIMARY KEY(generation,id), FOREIGN KEY(generation,document_id) REFERENCES documents(generation,id) ON DELETE CASCADE) STRICT;
CREATE TABLE effect_links (generation TEXT NOT NULL, id TEXT NOT NULL, effect_id TEXT NOT NULL, document_id TEXT NOT NULL, block_id TEXT NOT NULL, frequency TEXT NOT NULL, context TEXT NOT NULL, raw_term TEXT NOT NULL, raw_json TEXT NOT NULL, PRIMARY KEY(generation,id), FOREIGN KEY(generation,effect_id) REFERENCES effects(generation,id) ON DELETE CASCADE, FOREIGN KEY(generation,document_id) REFERENCES documents(generation,id), FOREIGN KEY(generation,block_id) REFERENCES blocks(generation,id)) STRICT;
CREATE INDEX effect_links_lookup ON effect_links(generation,effect_id,document_id);
CREATE TABLE embedding_namespaces (generation TEXT NOT NULL REFERENCES generations(id) ON DELETE CASCADE, model TEXT NOT NULL, dimensions INTEGER NOT NULL CHECK(dimensions>0), status TEXT NOT NULL CHECK(status IN ('building','ready','partial')), indexed_count INTEGER NOT NULL DEFAULT 0 CHECK(indexed_count>=0), PRIMARY KEY(generation,model), UNIQUE(generation,model,dimensions)) STRICT;
CREATE TABLE embeddings (generation TEXT NOT NULL, entity_type TEXT NOT NULL CHECK(entity_type IN ('chunk','effect')), entity_id TEXT NOT NULL, model TEXT NOT NULL, dimensions INTEGER NOT NULL, content_hash TEXT NOT NULL, vector BLOB NOT NULL CHECK(length(vector)=dimensions*4), norm REAL NOT NULL CHECK(norm>0), PRIMARY KEY(generation,entity_type,entity_id,model), FOREIGN KEY(generation,model,dimensions) REFERENCES embedding_namespaces(generation,model,dimensions) ON DELETE CASCADE) STRICT;
CREATE TRIGGER embeddings_entity_insert BEFORE INSERT ON embeddings BEGIN
 SELECT CASE WHEN NEW.entity_type='chunk' AND NOT EXISTS(SELECT 1 FROM chunks WHERE generation=NEW.generation AND id=NEW.entity_id AND content_hash=NEW.content_hash) THEN RAISE(ABORT,'Invalid chunk embedding provenance') END;
 SELECT CASE WHEN NEW.entity_type='effect' AND NOT EXISTS(SELECT 1 FROM effects WHERE generation=NEW.generation AND id=NEW.entity_id) THEN RAISE(ABORT,'Invalid effect embedding provenance') END;
END;
CREATE VIRTUAL TABLE documents_fts USING fts5(generation UNINDEXED,id UNINDEXED,inn,label,file,content,tokenize='unicode61');
CREATE VIRTUAL TABLE chunks_fts USING fts5(generation UNINDEXED,id UNINDEXED,content,tokenize='unicode61');
CREATE VIRTUAL TABLE effects_fts USING fts5(generation UNINDEXED,id UNINDEXED,name,aliases,tokenize='unicode61');
